//! The Hook API import whitelist.
//!
//! This is the single source of truth for which functions a Hook is allowed
//! to import from module `env`, and with which signature. It is generated by
//! hand from `hook/extern.h` (upstream `Xahau/xahaud`, branch `release`) and
//! must stay in sync with `rshooks-core`'s `src/api.rs`, which mirrors the same
//! header. A unit test below cross-checks the two so they can never drift.

use wasm_encoder::ValType;

/// One entry in the Hook API whitelist: an import name, its parameter types,
/// and its single result type.
#[derive(Debug, Clone, Copy)]
pub struct ApiFn {
    /// The import name (as it appears after `wasm_import_module = "env"`).
    pub name: &'static str,
    /// Parameter types, in order.
    pub params: &'static [ValType],
    /// The single result type (every Hook API function, including `_g`,
    /// returns exactly one value).
    pub result: ValType,
}

const I32: ValType = ValType::I32;
const I64: ValType = ValType::I64;

